	open fun rkAverage(forcing: fv_FvStepForcing?) {
		var avg: FN194? = FN194 __lam1@{ cur, old ->
				var i: Long = 0L
				__L2@ while (java.lang.Long.compareUnsigned(i, cur!!.size()) < 0) {
					cur!!.a!![i.toInt()] = 0.5 * (old!!.a!![i.toInt()] + cur!!.a!![i.toInt()])
					i++
				}
				return@__lam1
			}
		var nc: Long = (this.state_!!.cell_a)!!.size()
		var s: Int = 0
		__L3@ while (s < this.state_!!.n_species) {
			var base: Long = s.toLong() * nc
			var i_2: Long = 0L
			__L4@ while (java.lang.Long.compareUnsigned(i_2, nc) < 0) {
				var final_area: Double = (this.state_!!.cell_a)!!.a!![i_2.toInt()]
				var sum_area: Double = this.rk_cell_a_!!.a!![i_2.toInt()] + final_area
				(this.state_!!.cell_phi)!!.a!![(base + i_2).toInt()] = if (sum_area > 0.0) ((this.rk_cell_a_!!.a!![i_2.toInt()] * this.rk_cell_phi_!!.a!![(base + i_2).toInt()]) + (final_area * (this.state_!!.cell_phi)!!.a!![(base + i_2).toInt()])) / sum_area else this.rk_cell_phi_!!.a!![(base + i_2).toInt()]
				i_2++
			}
			s++
		}
		avg!!.invoke(this.state_!!.cell_a, this.rk_cell_a_)
		avg!!.invoke(this.state_!!.cell_q, this.rk_cell_q_)
		var n: Int = 0
		__L5@ while (n < this.mesh_!!.n_nodes()) {
			var un: Long = n.toLong()
			if ((((this.mesh_!!.node_kind)!!.a!![un.toInt()]).toInt() and 0xFF) == 1) {
				n++
				continue@__L5
			}
			if ((!((forcing!!.node_fixed_head)!!.get_IsNull())) && ((forcing!!.node_fixed_head)!!.get_Item_ul(un) as Double).isFinite()) {
				(this.state_!!.node_head)!!.a!![un.toInt()] = 0.5 * (this.rk_node_head_!!.a!![un.toInt()] + (this.state_!!.node_head)!!.a!![un.toInt()])
				n++
				continue@__L5
			}
			if (this.algebraicActive(n)) {
				(this.state_!!.node_head)!!.a!![un.toInt()] = 0.5 * (this.rk_node_head_!!.a!![un.toInt()] + (this.state_!!.node_head)!!.a!![un.toInt()])
				(this.state_!!.node_volume)!!.a!![un.toInt()] = cpp.M.max_d_d(0.0, this.node_carry_!!.a!![un.toInt()])
				n++
				continue@__L5
			}
			var vol: Double = 0.5 * (this.rk_node_vol_!!.a!![un.toInt()] + (this.state_!!.node_volume)!!.a!![un.toInt()])
			(this.state_!!.node_volume)!!.a!![un.toInt()] = vol
			(this.state_!!.node_head)!!.a!![un.toInt()] = (this.mesh_!!.node_invert)!!.a!![un.toInt()] + this.nodeDepthFromVolume(n, vol)
			n++
		}
		var avg_delta: FN194? = FN194 __lam6@{ cur_2, base_2 ->
				var i_3: Long = 0L
				__L7@ while (java.lang.Long.compareUnsigned(i_3, cur_2!!.size()) < 0) {
					cur_2!!.a!![i_3.toInt()] = base_2!!.a!![i_3.toInt()] + (0.5 * (cur_2!!.a!![i_3.toInt()] - base_2!!.a!![i_3.toInt()]))
					i_3++
				}
				return@__lam6
			}
		avg_delta!!.invoke(this.node_exch_, this.rk_exch_)
		avg_delta!!.invoke(this.node_in_, this.rk_in_)
		avg_delta!!.invoke(this.node_out_, this.rk_out_)
		avg_delta!!.invoke(this.flood_vol_, this.rk_flood_)
		avg_delta!!.invoke(this.cell_q_int_, this.rk_qint_)
		avg_delta!!.invoke(this.node_carry_, this.rk_carry_)
		avg_delta!!.invoke(this.dummy_vol_, this.rk_dummy_)
		avg_delta!!.invoke(this.unmet_withdrawal_, this.rk_unmet_)
		if (this.water_tracking_) {
			this.water_!!.averageDelta(this.rk_water_)
		}
		var n_2: Int = 0
		__L8@ while (n_2 < this.mesh_!!.n_nodes()) {
			var un_2: Long = n_2.toLong()
			if (this.algebraicActive(n_2) && (!((!((forcing!!.node_fixed_head)!!.get_IsNull())) && ((forcing!!.node_fixed_head)!!.get_Item_ul(un_2) as Double).isFinite()))) {
				(this.state_!!.node_volume)!!.a!![un_2.toInt()] = cpp.M.max_d_d(0.0, this.node_carry_!!.a!![un_2.toInt()])
			}
			n_2++
		}
		if (this.tpa_) {
			(this.state_!!.cell_tpa)!!.Assign_VecT(this.rk_tpa_)
		}
		this.refreshDepths()
	}

	open fun faceSide(face: Int, cell: Int, node: Int, zstar: Double, dir: Int, u_interior: Double, out: fv_kernels_FaceState?, i1_raw: cpp.RefD?, z_side: cpp.RefD?, measure_only: Boolean) {
		var uf: Long = face.toLong()
		var g: fv_FvGeometry? = null
		var eta: Double = 0.0
		var h_raw: Double = 0.0
		var u: Double = 0.0
		z_side!!.set(0.0)
		var centred: Boolean = false
		var uc_cached: Long = 0L
		var node_head_ghost: cpp.RefZ.Cell = cpp.RefZ.Cell(false)
		var gf: fv_FvGeometry? = (this.mesh_!!.geom)!!.a!![((this.mesh_!!.face_geom)!!.a!![uf.toInt()]).toLong().toInt()] as fv_FvGeometry?
		if (cell >= 0) {
			var uc: Long = cell.toLong()
			g = (this.mesh_!!.geom)!!.a!![((this.mesh_!!.cell_geom)!!.a!![uc.toInt()]).toLong().toInt()] as fv_FvGeometry?
			if ((this.opts_!!.order < 2) || (!((this.cell_ho2_!!.a!![uc.toInt()]).toInt() != 0))) {
				eta = this.cell_eta_!!.a!![uc.toInt()]
				h_raw = (this.state_!!.cell_h)!!.a!![uc.toInt()]
				u = dir.toDouble() * this.cell_u_!!.a!![uc.toInt()]
				z_side!!.set((this.mesh_!!.cell_zb)!!.a!![uc.toInt()])
				centred = true
				uc_cached = uc
			} else {
				var is_left: Boolean = (this.mesh_!!.face_cl)!!.a!![uf.toInt()] == cell
				var sgn: Double = if (is_left) ((this.mesh_!!.face_dir_l)!!.a!![uf.toInt()]).toDouble() else -((this.mesh_!!.face_dir_r)!!.a!![uf.toInt()]).toDouble()
				var half: Double = (sgn * 0.5) * (this.mesh_!!.cell_dx)!!.a!![uc.toInt()]
				z_side!!.set((this.mesh_!!.cell_zb)!!.a!![uc.toInt()] + ((this.mesh_!!.cell_dzdx)!!.a!![uc.toInt()] * half))
				eta = this.cell_eta_!!.a!![uc.toInt()] + (this.cell_eta_slope_!!.a!![uc.toInt()] * half)
				h_raw = cpp.M.max_d_d(0.0, eta - z_side!!.get())
				u = dir.toDouble() * (this.cell_u_!!.a!![uc.toInt()] + (this.cell_u_slope_!!.a!![uc.toInt()] * half))
			}
		} else {
			var other: Int = (if ((this.mesh_!!.face_cl)!!.a!![uf.toInt()] >= 0) cpp.RefI.Arr((this.mesh_!!.face_cl)!!.a, uf.toInt()) else cpp.RefI.Arr((this.mesh_!!.face_cr)!!.a, uf.toInt()))!!.get()
			var uo: Long = other.toLong()
			g = (this.mesh_!!.geom)!!.a!![((this.mesh_!!.cell_geom)!!.a!![uo.toInt()]).toLong().toInt()] as fv_FvGeometry?
			if (node >= 0) {
				var und: Long = node.toLong()
				eta = (this.state_!!.node_head)!!.a!![und.toInt()]
				h_raw = cpp.M.max_d_d(0.0, eta - (this.mesh_!!.face_zb)!!.a!![uf.toInt()])
				u = u_interior
				z_side!!.set((this.mesh_!!.face_zb)!!.a!![uf.toInt()])
				node_head_ghost.v = true
				if (((!(this.node_pass_!!.empty())) && (((this.node_pass_!!.a!![und.toInt()]).toInt() and 0xFF) != 0)) && this.algebraicActive(node)) {
					var nb2: Int = (this.mesh_!!.node_face_ptr)!!.a!![und.toInt()]
					var ne2: Int = (this.mesh_!!.node_face_ptr)!!.a!![(und + 1L).toInt()]
					var p2: Int = nb2
					__L1@ while (p2 < ne2) {
						var of: Int = (this.mesh_!!.node_face_idx)!!.a!![p2.toLong().toInt()]
						if (of == face) {
							p2++
							continue@__L1
						}
						var uof: Long = of.toLong()
						var oc: Int = (if ((this.mesh_!!.face_cl)!!.a!![uof.toInt()] >= 0) cpp.RefI.Arr((this.mesh_!!.face_cl)!!.a, uof.toInt()) else cpp.RefI.Arr((this.mesh_!!.face_cr)!!.a, uof.toInt()))!!.get()
						if (oc >= 0) {
							var uoc: Long = oc.toLong()
							eta = this.cell_eta_!!.a!![uoc.toInt()]
							h_raw = (this.state_!!.cell_h)!!.a!![uoc.toInt()]
							z_side!!.set((this.mesh_!!.cell_zb)!!.a!![uoc.toInt()])
							node_head_ghost.v = false
						}
						p2++
					}
				}
			} else {
				eta = this.cell_eta_!!.a!![uo.toInt()]
				h_raw = (this.state_!!.cell_h)!!.a!![uo.toInt()]
				u = -u_interior
				z_side!!.set((this.mesh_!!.face_zb)!!.a!![uf.toInt()])
			}
		}
		if (measure_only) {
			i1_raw!!.set(0.0)
			out!!.MoveFrom(fv_kernels_FaceState())
			return
		}
		var tpa_side: Boolean = false
		if (this.tpa_) {
			if (cell >= 0) {
				tpa_side = this.tpaCell(cell.toLong())
			} else {
				var other2: Int = (if ((this.mesh_!!.face_cl)!!.a!![uf.toInt()] >= 0) cpp.RefI.Arr((this.mesh_!!.face_cl)!!.a, uf.toInt()) else cpp.RefI.Arr((this.mesh_!!.face_cr)!!.a, uf.toInt()))!!.get()
				if (other2 >= 0) {
					var interior_tpa: Boolean = this.tpaCell(other2.toLong())
					if (node >= 0) {
						tpa_side = interior_tpa && ((this.mesh_!!.node_sur_depth)!!.a!![node.toLong().toInt()] > 0.0)
					} else {
						tpa_side = interior_tpa
					}
				}
			}
		}
		if (tpa_side) {
			i1_raw!!.set(F_fv_kernels.tpaI1OfDepth(g, eta - z_side!!.get()))
			var h_star_t: Double = eta - zstar
			var a_t: Double = F_fv_kernels.tpaAreaOfDepth(gf, h_star_t)
			if (a_t < F_fv_kernels.kDryArea) {
				a_t = F_fv_kernels.kDryArea
			}
			out!!.a = a_t
			out!!.u = u
			out!!.q = a_t * u
			out!!.c = F_fv_kernels.celerity(a_t, gf!!.t_slot)
			out!!.i1 = F_fv_kernels.tpaI1OfDepth(gf, h_star_t)
			out!!.press = if (this.mixed_wave_ && this.mw_rh_) (1).toByte() else (0).toByte()
			return
		}
		if ((cell >= 0) && (h_raw > F_fv_kernels.kDryDepth)) {
			if (centred) {
				i1_raw!!.set(this.cell_i1_!!.a!![uc_cached.toInt()])
			} else {
				i1_raw!!.set(F_fv_kernels.closureI1(g!!.closure_tbl, h_raw))
				F_perf.count(perf_FvCounter.n_fv_geom_i1, 1L)
			}
		} else {
			i1_raw!!.set(0.0)
		}
		var h_star: Double = cpp.M.max_d_d(0.0, eta - zstar)
		if (h_star <= F_fv_kernels.kDryDepth) {
			out!!.MoveFrom(fv_kernels_FaceState())
			return
		}
		var finish: FN200? = FN200 __lam2@{ o ->
				if (!this.mixed_wave_) {
					return@__lam2
				}
				o!!.press = if ((this.mw_rh_ && (!(((gf!!.is_open).toInt() and 0xFF) != 0))) && (h_star >= gf!!.y_full)) (1).toByte() else (0).toByte()
				if ((node_head_ghost.v && (node >= 0)) && ((this.mesh_!!.node_sur_depth)!!.a!![node.toLong().toInt()] <= 0.0)) {
					o!!.press = if (this.mw_rh_) (2).toByte() else (0).toByte()
				}
				return@__lam2
			}
		if ((centred && (gf === g)) && (h_star == h_raw)) {
			out!!.a = this.cell_ah_!!.a!![uc_cached.toInt()]
			out!!.u = u
			out!!.q = out!!.a * u
			out!!.c = F_fv_kernels.celerity(out!!.a, this.cell_t_!!.a!![uc_cached.toInt()])
			out!!.i1 = this.cell_i1_!!.a!![uc_cached.toInt()]
			finish!!.invoke(out)
			return
		}
		F_perf.count(perf_FvCounter.n_fv_geom_area, 1L)
		F_perf.count(perf_FvCounter.n_fv_geom_width, 1L)
		F_perf.count(perf_FvCounter.n_fv_geom_i1, 1L)
		var e: fv_kernels_ClosureEval? = F_fv_kernels.closureEval__rFvClosure_d(gf!!.closure_tbl, h_star)
		out!!.a = e!!.a
		out!!.u = u
		out!!.q = e!!.a * u
		out!!.c = F_fv_kernels.celerity(e!!.a, e!!.t)
		out!!.i1 = e!!.i1
		finish!!.invoke(out)
	}

	open fun cacheClosure(uc: Long, g: fv_FvGeometry?, h__p: Double, radius: cpp.PtrD?) {
		val h: cpp.RefD.Cell = cpp.RefD.Cell(h__p)
		if ((h.v > F_fv_kernels.kDryDepth) && (!this.tpaCell(uc))) {
			F_perf.count(perf_FvCounter.n_fv_geom_area, 1L)
			F_perf.count(perf_FvCounter.n_fv_geom_width, 1L)
			F_perf.count(perf_FvCounter.n_fv_geom_i1, 1L)
			var e: fv_kernels_ClosureEval? = if (!(radius!!.get_IsNull())) F_fv_kernels.closureEval__rFvClosure_d_rd(g!!.closure_tbl, h.v, radius!!.ref_Deref()) else F_fv_kernels.closureEval__rFvClosure_d(g!!.closure_tbl, h.v)
			this.cell_ah_!!.a!![uc.toInt()] = e!!.a
			this.cell_t_!!.a!![uc.toInt()] = e!!.t
			this.cell_i1_!!.a!![uc.toInt()] = e!!.i1
		} else {
			this.cell_ah_!!.a!![uc.toInt()] = 0.0
			this.cell_t_!!.a!![uc.toInt()] = 0.0
			this.cell_i1_!!.a!![uc.toInt()] = 0.0
			if (!(radius!!.get_IsNull())) {
				(radius!!.ref_Deref())!!.set(F_fv_kernels.hydRadOfDepth(g, (if (this.tpaCell(uc)) FRef.f_fv_FvGeometry_y_full(g) else h)!!.get()))
			}
		}
	}

	open fun computeUfGradients(cells: cpp.VecI?) {
		var nc: Int = this.mesh_!!.n_cells()
		var grad_for: FN74? = FN74 __lam1@{ c ->
				var uc: Long = c.toLong()
				this.uf_grad_!!.a!![uc.toInt()] = 0.0
				if (!((this.cell_active_!!.a!![uc.toInt()]).toInt() != 0)) {
					return@__lam1
				}
				var h: Double = (this.state_!!.cell_h)!!.a!![uc.toInt()]
				if (h <= F_fv_kernels.kDryDepth) {
					return@__lam1
				}
