				if (u == 0.0) {
					return@__lam1
				}
				var cond: Int = (this.mesh_!!.cell_conduit)!!.a!![uc.toInt()]
				var dx_c: Double = (this.mesh_!!.cell_dx)!!.a!![uc.toInt()]
				var uL: Double = u
				var uR: Double = u
				var dsum: Double = 0.0
				var faces: IntArray? = intArrayOf((this.mesh_!!.cell_face0)!!.a!![uc.toInt()], (this.mesh_!!.cell_face1)!!.a!![uc.toInt()])
				var sides: ByteArray? = byteArrayOf((this.mesh_!!.cell_side0)!!.a!![uc.toInt()], (this.mesh_!!.cell_side1)!!.a!![uc.toInt()])
				var e: Int = 0
				__L2@ while (e < 2) {
