					var nb: Int = (if ((cpp.PtrB(sides, 0L).get_Item_i(e) as Byte).toInt() == 0) cpp.RefI.Arr((this.mesh_!!.face_cr)!!.a, uf.toInt()) else cpp.RefI.Arr((this.mesh_!!.face_cl)!!.a, uf.toInt()))!!.get()
