	override fun divergence(d: fv_INetworkSolver_Divergence?): Boolean {
		if (this.div_link_ < 0) {
			return false
		}
		d!!.link = this.div_link_
		d!!.value = this.div_value_
		d!!.what = this.div_what_
		return true
	}

