	open fun trackAcceptedWater(enabled: Boolean) {
		this.water_tracking_ = enabled
		if (enabled && (this.mesh_ !== null)) {
			this.water_!!.resize((this.mesh_!!.n_faces()).toLong(), (this.mesh_!!.struct_link)!!.size(), (this.mesh_!!.n_cells()).toLong(), (this.mesh_!!.n_nodes()).toLong())
		} else {
			val __o1 = fv_AcceptedWaterVolumes()
			__o1.face_forward = cpp.VecD()
			__o1.face_reverse = cpp.VecD()
			__o1.structure_forward = cpp.VecD()
			__o1.structure_reverse = cpp.VecD()
			__o1.cell_lateral = cpp.VecD()
			__o1.cell_loss = cpp.VecD()
			__o1.node_deficit = cpp.VecD()
			__o1.face_lateral_left = cpp.VecD()
			__o1.face_lateral_right = cpp.VecD()
			__o1.face_spill = cpp.VecD()
			this.water_!!.MoveFrom(__o1)
		}
		this.save_water_!!.Assign(this.water_)
		this.rk_water_!!.Assign(this.water_)
	}

