	open fun bookDivertedLateral(un: Long, dt: Double, forcing: fv_FvStepForcing?) {
		if ((this.node_lat_div_!!.empty() || (!(((this.node_lat_div_!!.a!![un.toInt()]).toInt() and 0xFF) != 0))) || (!(!((forcing!!.node_lateral)!!.get_IsNull())))) {
			return
		}
		var lat: Double = (forcing!!.node_lateral)!!.get_Item_ul(un) as Double
		if (lat > 0.0) {
			this.node_out_!!.a!![un.toInt()] += lat * dt
		}
	}

