	open fun nodeLateral(forcing: fv_FvStepForcing?, un: Long): Double {
		if ((!(this.node_lat_div_!!.empty())) && (((this.node_lat_div_!!.a!![un.toInt()]).toInt() and 0xFF) != 0)) {
			return 0.0
		}
		return if (!((forcing!!.node_lateral)!!.get_IsNull())) (forcing!!.node_lateral)!!.get_Item_ul(un) as Double else 0.0
	}

	open fun algebraicActive(n: Int): Boolean {
		var un: Long = n.toLong()
		if (!(((this.node_alg_!!.a!![un.toInt()]).toInt() and 0xFF) != 0)) {
			return false
		}
		if (((((this.mesh_!!.node_can_pond)!!.a!![un.toInt()]).toInt() and 0xFF) != 0) && ((this.state_!!.node_volume)!!.a!![un.toInt()] > this.node_vfull_!!.a!![un.toInt()])) {
			return false
		}
		return true
	}

	open fun incidentPressurized(un: Long): Boolean {
		var p: Int = (this.mesh_!!.node_face_ptr)!!.a!![un.toInt()]
		__L1@ while (p < (this.mesh_!!.node_face_ptr)!!.a!![(un + 1L).toInt()]) {
			var uf: Long = ((this.mesh_!!.node_face_idx)!!.a!![p.toLong().toInt()]).toLong()
			var c: Int = (if ((this.mesh_!!.face_cl)!!.a!![uf.toInt()] >= 0) cpp.RefI.Arr((this.mesh_!!.face_cl)!!.a, uf.toInt()) else cpp.RefI.Arr((this.mesh_!!.face_cr)!!.a, uf.toInt()))!!.get()
			if (c < 0) {
				p++
				continue@__L1
			}
			var uc: Long = c.toLong()
			if (this.tpaCell(uc)) {
				return true
			}
			var g: fv_FvGeometry? = (this.mesh_!!.geom)!!.a!![((this.mesh_!!.cell_geom)!!.a!![uc.toInt()]).toLong().toInt()] as fv_FvGeometry?
			if ((!(((g!!.is_open).toInt() and 0xFF) != 0)) && ((this.state_!!.cell_h)!!.a!![uc.toInt()] >= g!!.y_crown)) {
				return true
			}
			p++
		}
		return false
	}

	open fun nodeQDummy(un: Long): Double {
		return if (this.node_qdummy_!!.empty()) 0.0 else this.node_qdummy_!!.a!![un.toInt()]
	}

	open fun ltsEligible(): Boolean {
		return ((this.opts_!!.lts && (this.opts_!!.time_integration != fv_TimeIntegration.RK2)) && (this.state_ !== null)) && (this.state_!!.n_species == 0)
	}

	open fun faceIsLive(f: Int): Boolean {
		return this.all_faces_live_ || ((!(this.live_stamp_!!.empty())) && (this.live_stamp_!!.a!![f.toLong().toInt()] == this.live_gen_))
	}

	open fun tpaCell(uc: Long): Boolean {
		return this.tpa_ && ((((this.state_!!.cell_tpa)!!.a!![uc.toInt()]).toInt() and 0xFF) != 0)
	}

